"439 :     private void getDefinition(Node n, Node parent) {
440 :       AbstractCfgNodeTraversalCallback gatherCb =
441 :         new AbstractCfgNodeTraversalCallback() {
442 : 
443 :         @Override
444 :         public void visit(NodeTraversal t, Node n, Node parent) {
445 :           switch (n.getType()) {
446 :             case Token.NAME:
447 :               if (n.getString().equals(varName) && n.hasChildren()) {
448 :                 def = n;
449 :               }
450 :               return;
451 : 
452 :             case Token.ASSIGN:
453 :               Node lhs = n.getFirstChild();
454 :               if (lhs.isName() && lhs.getString().equals(varName)) {
455 :                 def = n;
456 :               }
457 :               return;
458 :           }
459 :         }
460 :       };
461 :       NodeTraversal.traverse(compiler, n, gatherCb);
